    for i in range(c, -1, -1):
        if grid[r][i] == 9:
            d['left'] = c - i
            break
    else:
        d['left'] = float('inf')

    # Right
    for i in range(c, w):
        if grid[r][i] == 9:
            d['right'] = i - c + 1
