    """
    Rule: A cell transforms from 4 to 2 if and only if it is STRICTLY between 
    two wall cells (9s) in exactly ONE direction (either row OR column, but NOT both).

    Implementation: First do H-pass, then V-pass on remaining cells.
    """
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    # Horizontal pass
    for r in range(h):
        row = grid[r]
        walls = [c for c, v in enumerate(row) if v == 9]

        for i in range(len(walls) - 1):
            start_wall, end_wall = walls[i], walls[i+1]
            for c in range(start_wall + 1, end_wall):
                if row[c] == 4:
                    result[r][c] = 2

    # Vertical pass - only mark cells NOT already transformed
    h_transformed = set((r,c) for r in range(h) for c in range(w) if result[r][c] == 2)

    for c in range(w):
        col_vals = [grid[r][c] for r in range(h)]
        walls = [r for r, v in enumerate(col_vals) if v == 9]

        for i in range(len(walls) - 1):
